-- Synthetic local-only attack scenarios, after existing auth-security/delivery/operations.
-- No production credentials, accounts or business rows. Every new action rolls back.
DO $$ BEGIN IF inet_server_addr() IS DISTINCT FROM '127.0.0.1'::inet THEN RAISE EXCEPTION 'Requires local test server'; END IF; END $$;
BEGIN;
CREATE TABLE test_auth.profile_snapshot AS SELECT to_jsonb(p) AS value FROM public.profiles p WHERE id='10000000-0000-4000-8000-000000000003';
CREATE TABLE test_auth.audit_results (scenario text, passed boolean DEFAULT true);
GRANT INSERT,SELECT ON test_auth.audit_results TO authenticated;
SET ROLE authenticated;
SELECT test_auth.login(3,'20000000-0000-4000-8000-000000000002');
SELECT set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb || '{"user_metadata":{"role":"admin","roles":["admin"],"workspace_id":"20000000-0000-4000-8000-000000000001"},"app_metadata":{"role":"admin","roles":["admin"]},"is_admin":true,"roles":["admin"]}'::jsonb)::text,false);
SELECT test_auth.assert((public.get_my_access_context('20000000-0000-4000-8000-000000000002')->'roles')='["tecnico"]','forged role claims do not override database role');
SELECT test_auth.assert((SELECT NOT is_admin AND is_technician FROM public.get_current_actor_context()),'actor remains technician');
SELECT test_auth.assert(NOT public.can_manage_workspace('20000000-0000-4000-8000-000000000002'),'manager check false despite forged admin');
INSERT INTO test_auth.audit_results(scenario) VALUES('Forged user_metadata, app_metadata, roles, is_admin ignored for authorization');
SELECT test_auth.expect_error('UPDATE public.employees SET roles=ARRAY[''admin''] WHERE id=(SELECT id FROM test_auth.fixture WHERE name=''rejoined_employee'')','42501');
SELECT test_auth.expect_error('SELECT public.update_employee_access((SELECT id FROM test_auth.fixture WHERE name=''rejoined_employee''),''Self promotion'',ARRAY[''admin''])','42501');
SELECT test_auth.expect_error('INSERT INTO public.profiles(id,workspace_id,role) VALUES(''10000000-0000-4000-8000-000000000003'',''20000000-0000-4000-8000-000000000002'',''admin'')','42501');
SELECT test_auth.expect_error('UPDATE public.profiles SET role=''admin'',workspace_id=''20000000-0000-4000-8000-000000000002'' WHERE id=''10000000-0000-4000-8000-000000000003''','42501');
SELECT test_auth.expect_error('UPDATE public.workspace_memberships SET member_kind=''owner'',employee_id=NULL WHERE user_id=''10000000-0000-4000-8000-000000000003''','42501');
SELECT test_auth.expect_error('INSERT INTO public.workspace_memberships(workspace_id,user_id,member_kind) VALUES(''20000000-0000-4000-8000-000000000001'',''10000000-0000-4000-8000-000000000003'',''owner'')','42501');
SELECT test_auth.expect_error('UPDATE public.workspaces SET owner_id=''10000000-0000-4000-8000-000000000003'' WHERE id=''20000000-0000-4000-8000-000000000002''','42501');
SELECT test_auth.expect_error('UPDATE public.employee_auth_state SET manual_blocked=false','42501');
INSERT INTO test_auth.audit_results(scenario) VALUES('Self-promotion RPC and direct mutation of roles, profiles, memberships, owner and block state denied');
SELECT test_auth.expect_error('SELECT public.create_workspace_invitation(''20000000-0000-4000-8000-000000000002'',''Fake admin'',''fake-admin@example.invalid'',ARRAY[''admin''])','42501');
SELECT test_auth.expect_error('SELECT public.cancel_workspace_invitation((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''))','42501');
SELECT test_auth.expect_error('SELECT public.reissue_workspace_invitation((SELECT id FROM test_auth.fixture WHERE name=''delivery_invite''))','42501');
SELECT test_auth.expect_error('UPDATE public.workspace_invitations SET email=''fixture3@example.invalid''','42501');
SELECT test_auth.expect_error('SELECT public.list_workspace_staff(''20000000-0000-4000-8000-000000000002'')','42501');
SELECT test_auth.expect_error('SELECT public.get_my_workspace_invitations(''20000000-0000-4000-8000-000000000002'')','42501');
SELECT test_auth.expect_error('SELECT public.set_employee_account_blocked((SELECT id FROM test_auth.fixture WHERE name=''admin_employee''),true,''Forged admin'')','42501');
SELECT test_auth.expect_error('SELECT public.set_employee_removed((SELECT id FROM test_auth.fixture WHERE name=''admin_employee''),true)','42501');
SELECT test_auth.expect_error('SELECT public.revoke_employee_sessions((SELECT id FROM test_auth.fixture WHERE name=''admin_employee''))','42501');
INSERT INTO test_auth.audit_results(scenario) VALUES('Team management, invitations, block, remove and revoke denied');
SELECT test_auth.expect_error('SELECT public.update_workspace_company_config(''5511999999999'')','42501');
SELECT test_auth.expect_error('SELECT public.update_workspace_tracker_config(''{"customization":{"modules":true},"modules":{"inventory":true}}'')','P0001');
SELECT test_auth.expect_error('SELECT public.get_daily_report()','42501');
SELECT test_auth.expect_error('SELECT public.save_inventory_item(''{"name":"Forged admin item"}'')');
SELECT test_auth.expect_error('SELECT public.adjust_inventory_stock((SELECT id FROM test_auth.fixture WHERE name=''inventory_item''),NULL,100,''Forged admin'')');
SELECT test_auth.expect_error('INSERT INTO storage.objects(bucket_id,name) VALUES(''workspace_logos'',''20000000-0000-4000-8000-000000000002/forged.png'')','42501');
INSERT INTO test_auth.audit_results(scenario) VALUES('Company configuration, report, inventory changes and logo upload denied');
DO $$
DECLARE v_table text; v_count integer;
BEGIN
  FOREACH v_table IN ARRAY ARRAY['device_models','defect_options','checklist_templates','fornecedores','outsourced_companies'] LOOP
    EXECUTE format('UPDATE public.%I SET workspace_id=workspace_id',v_table);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    PERFORM test_auth.assert(v_count=0,'technician catalog update denied: '||v_table);
    EXECUTE format('DELETE FROM public.%I',v_table);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    PERFORM test_auth.assert(v_count=0,'technician catalog delete denied: '||v_table);
  END LOOP;
END $$;
INSERT INTO test_auth.audit_results(scenario) VALUES('RLS catalog update/delete affect zero rows despite UI admin');
SELECT set_config('request.headers','{"x-workspace-id":"20000000-0000-4000-8000-000000000001","x-role":"admin","x-is-admin":"true"}',false);
SELECT test_auth.expect_error('SELECT public.get_current_actor_context()','42501');
SELECT test_auth.expect_error('SELECT public.get_my_access_context(''20000000-0000-4000-8000-000000000001'')','42501');
SELECT test_auth.assert(NOT public.can_manage_workspace('20000000-0000-4000-8000-000000000001'),'foreign workspace manager denied');
SELECT test_auth.expect_error('SELECT * FROM public.tickets','42501');
INSERT INTO test_auth.audit_results(scenario) VALUES('Forged company selection and admin headers denied');
RESET ROLE;
SELECT test_auth.assert((SELECT roles=ARRAY['tecnico'] FROM public.employees WHERE id=(SELECT id FROM test_auth.fixture WHERE name='rejoined_employee')),'employee roles unchanged');
SELECT test_auth.assert((SELECT member_kind='employee' AND status='active' FROM public.workspace_memberships WHERE user_id='10000000-0000-4000-8000-000000000003'),'employee membership unchanged');
SELECT test_auth.assert((SELECT owner_id='10000000-0000-4000-8000-000000000002' FROM public.workspaces WHERE id='20000000-0000-4000-8000-000000000002'),'company owner unchanged');
SELECT test_auth.assert(NOT EXISTS(SELECT 1 FROM public.workspace_invitations WHERE email='fake-admin@example.invalid'),'no forged admin invitation');
SELECT test_auth.assert(NOT EXISTS(SELECT 1 FROM public.inventory_items WHERE name='Forged admin item'),'no forbidden inventory item');
SELECT test_auth.assert(NOT EXISTS(SELECT 1 FROM storage.objects WHERE name LIKE '%/forged.png'),'no forbidden logo');
SELECT test_auth.assert((SELECT jsonb_agg(to_jsonb(p)) FROM public.profiles p WHERE id='10000000-0000-4000-8000-000000000003') IS NOT DISTINCT FROM (SELECT jsonb_agg(value) FROM test_auth.profile_snapshot),'legacy profile unchanged; its role does not grant access');
SELECT test_auth.assert((SELECT count(*)=1 FROM public.device_models WHERE name='Allowed catalog write'),'forbidden catalog changes did not remove legitimate row');
SELECT scenario,passed FROM test_auth.audit_results;
ROLLBACK;
SELECT 'PASS: targeted admin escalation rejected; legitimate database role, membership, owner and records unchanged' as result;
